CREATE TABLE recruitment_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE candidates(id INTEGER PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, linked_user_id TEXT REFERENCES users(id) ON DELETE RESTRICT, name TEXT NOT NULL, email TEXT NOT NULL, phone TEXT NOT NULL, location TEXT NOT NULL, years_experience REAL, notice_period_days INTEGER, merged_into INTEGER REFERENCES candidates(id) ON DELETE RESTRICT, CHECK(merged_into IS NULL OR merged_into<>id));
CREATE TABLE certifications(id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE candidate_certifications(candidate_id INTEGER NOT NULL REFERENCES candidates(id) ON DELETE RESTRICT, certification_id INTEGER NOT NULL REFERENCES certifications(id) ON DELETE RESTRICT, PRIMARY KEY(candidate_id,certification_id));
CREATE TABLE import_jobs(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, feed TEXT NOT NULL, status TEXT NOT NULL, processed INTEGER NOT NULL DEFAULT 0, errors INTEGER NOT NULL DEFAULT 0, examined INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE import_errors(id INTEGER PRIMARY KEY, job_id TEXT NOT NULL REFERENCES import_jobs(id) ON DELETE RESTRICT, row_number INTEGER NOT NULL, message TEXT NOT NULL);
CREATE TABLE source_identities(id INTEGER PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, feed TEXT NOT NULL, external_id TEXT NOT NULL, candidate_id INTEGER NOT NULL REFERENCES candidates(id) ON DELETE RESTRICT, UNIQUE(owner_id,feed,external_id));
CREATE TABLE source_records(id INTEGER PRIMARY KEY, identity_id INTEGER NOT NULL REFERENCES source_identities(id) ON DELETE RESTRICT, job_id TEXT REFERENCES import_jobs(id) ON DELETE RESTRICT, content_hash TEXT NOT NULL, raw_json TEXT NOT NULL, normalized_json TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(identity_id,content_hash));
CREATE TABLE field_provenance(candidate_id INTEGER NOT NULL REFERENCES candidates(id) ON DELETE RESTRICT, field TEXT NOT NULL, source_record_id INTEGER NOT NULL REFERENCES source_records(id) ON DELETE RESTRICT, PRIMARY KEY(candidate_id,field));
CREATE TABLE duplicate_reviews(id INTEGER PRIMARY KEY, left_id INTEGER NOT NULL REFERENCES candidates(id) ON DELETE RESTRICT, right_id INTEGER NOT NULL REFERENCES candidates(id) ON DELETE RESTRICT, score REAL NOT NULL, explanation TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', UNIQUE(left_id,right_id), CHECK(left_id<right_id));
CREATE TABLE merge_decisions(id INTEGER PRIMARY KEY, review_id INTEGER NOT NULL REFERENCES duplicate_reviews(id) ON DELETE RESTRICT, loser_id INTEGER NOT NULL REFERENCES candidates(id) ON DELETE RESTRICT, winner_id INTEGER NOT NULL REFERENCES candidates(id) ON DELETE RESTRICT, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE recruitment_rules(id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE rule_versions(id INTEGER PRIMARY KEY, rule_id INTEGER NOT NULL REFERENCES recruitment_rules(id) ON DELETE RESTRICT, version INTEGER NOT NULL, expression TEXT NOT NULL, priority INTEGER NOT NULL, active INTEGER NOT NULL DEFAULT 0, UNIQUE(rule_id,version));
CREATE UNIQUE INDEX one_active_rule_version ON rule_versions(rule_id) WHERE active=1;
CREATE TABLE evaluations(id INTEGER PRIMARY KEY, candidate_id INTEGER NOT NULL REFERENCES candidates(id) ON DELETE RESTRICT, rule_version_id INTEGER NOT NULL REFERENCES rule_versions(id) ON DELETE RESTRICT, input_snapshot TEXT NOT NULL, result_snapshot TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE workflow_templates(id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE template_versions(id INTEGER PRIMARY KEY, template_id INTEGER NOT NULL REFERENCES workflow_templates(id) ON DELETE RESTRICT, version INTEGER NOT NULL, UNIQUE(template_id,version));
CREATE TABLE workflow_nodes(version_id INTEGER NOT NULL REFERENCES template_versions(id) ON DELETE RESTRICT, name TEXT NOT NULL, PRIMARY KEY(version_id,name));
CREATE TABLE workflow_edges(version_id INTEGER NOT NULL, from_node TEXT NOT NULL, to_node TEXT NOT NULL, PRIMARY KEY(version_id,from_node,to_node), FOREIGN KEY(version_id,from_node) REFERENCES workflow_nodes(version_id,name) ON DELETE RESTRICT, FOREIGN KEY(version_id,to_node) REFERENCES workflow_nodes(version_id,name) ON DELETE RESTRICT);
CREATE TABLE recruitment_applications(id INTEGER PRIMARY KEY, candidate_id INTEGER NOT NULL REFERENCES candidates(id) ON DELETE RESTRICT, owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, submission_key TEXT NOT NULL, UNIQUE(owner_id,submission_key));
CREATE TABLE workflow_instances(id INTEGER PRIMARY KEY, application_id INTEGER NOT NULL UNIQUE REFERENCES recruitment_applications(id) ON DELETE RESTRICT, template_version_id INTEGER NOT NULL REFERENCES template_versions(id) ON DELETE RESTRICT, status TEXT NOT NULL DEFAULT 'active');
CREATE TABLE task_states(id INTEGER PRIMARY KEY, instance_id INTEGER NOT NULL REFERENCES workflow_instances(id) ON DELETE RESTRICT, node TEXT NOT NULL, status TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 0, responsible_id TEXT REFERENCES users(id) ON DELETE RESTRICT, UNIQUE(instance_id,node));
CREATE TABLE offers(id INTEGER PRIMARY KEY, instance_id INTEGER NOT NULL UNIQUE REFERENCES workflow_instances(id) ON DELETE RESTRICT, created_at TEXT NOT NULL);
CREATE TABLE queue_state(id INTEGER PRIMARY KEY, application_id INTEGER NOT NULL UNIQUE REFERENCES recruitment_applications(id) ON DELETE RESTRICT, priority INTEGER NOT NULL, sequence INTEGER NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'queued', claimed_by TEXT REFERENCES users(id) ON DELETE RESTRICT, version INTEGER NOT NULL DEFAULT 0);
CREATE TABLE queue_evaluations(queue_id INTEGER NOT NULL REFERENCES queue_state(id) ON DELETE RESTRICT, evaluation_id INTEGER NOT NULL UNIQUE REFERENCES evaluations(id) ON DELETE RESTRICT, PRIMARY KEY(queue_id,evaluation_id));
CREATE TABLE stress_runs(id INTEGER PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, result TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE Activity_Log(sequence INTEGER PRIMARY KEY, User_ID TEXT REFERENCES users(id) ON DELETE RESTRICT, Timestamp TEXT NOT NULL, Action_Type TEXT NOT NULL, entity TEXT NOT NULL, entity_id TEXT NOT NULL, correlation_id TEXT NOT NULL, Old_Value TEXT NOT NULL, New_Value TEXT NOT NULL, previous_hash TEXT NOT NULL, hash TEXT NOT NULL);
CREATE TRIGGER activity_no_update BEFORE UPDATE ON Activity_Log BEGIN SELECT RAISE(ABORT,'Activity_Log is append-only'); END;
CREATE TRIGGER activity_no_delete BEFORE DELETE ON Activity_Log BEGIN SELECT RAISE(ABORT,'Activity_Log is append-only'); END;
CREATE TRIGGER source_no_update BEFORE UPDATE ON source_records BEGIN SELECT RAISE(ABORT,'Source records are immutable'); END;
CREATE TRIGGER source_no_delete BEFORE DELETE ON source_records BEGIN SELECT RAISE(ABORT,'Source records are immutable'); END;
CREATE TABLE artist_skill_facts(artist_id TEXT NOT NULL REFERENCES artist_profiles(id) ON DELETE CASCADE, skill TEXT NOT NULL, PRIMARY KEY(artist_id,skill));
CREATE TRIGGER artist_skills_insert AFTER INSERT ON artist_profiles WHEN json_valid(NEW.skills) BEGIN
 INSERT OR IGNORE INTO artist_skill_facts SELECT NEW.id,value FROM json_each(NEW.skills) WHERE type='text';
END;
CREATE TRIGGER artist_skills_update AFTER UPDATE OF skills ON artist_profiles WHEN json_valid(NEW.skills) BEGIN
 DELETE FROM artist_skill_facts WHERE artist_id=NEW.id;
 INSERT OR IGNORE INTO artist_skill_facts SELECT NEW.id,value FROM json_each(NEW.skills) WHERE type='text';
END;
